const emailText = $input.first().json.text || '';

if (!emailText) {
  return [
    {
      json: {
        error: 'No email text found'
      }
    }
  ];
}

const text = emailText
  .replace(/\\n/g, '\n')
  .replace(/\\r/g, '')
  .replace(/&amp;/g, '&')
  .replace(/&#39;/g, "'")
  .replace(/&quot;/g, '"')
  .replace(/&nbsp;/g, ' ')
  .trim();

const budgetRegex = /Budget:\s*([^\n]+)/gi;
const budgets = [...text.matchAll(budgetRegex)];

const projects = [];

for (let i = 0; i < budgets.length; i++) {

  const budgetMatch = budgets[i];

  const budget = budgetMatch[1].trim();

  const projectStart =
    i === 0
      ? 0
      : budgets[i - 1].index + budgets[i - 1][0].length;

  const projectEnd =
    i + 1 < budgets.length
      ? budgets[i + 1].index
      : text.length;

  let titlePart = text
    .substring(projectStart, budgetMatch.index)
    .trim();

  let detailsPart = text
    .substring(
      budgetMatch.index + budgetMatch[0].length,
      projectEnd
    )
    .trim();

  // Remove email text before the first project
  titlePart = titlePart
    .replace(/^[\s\S]*?Projects\s*/i, '')
    .trim();

  // -------------------------
  // TITLE
  // -------------------------

  const titleLines = titlePart
    .split('\n')
    .map(line => line.trim())
    .filter(line => line);

  const title = titleLines.length
    ? titleLines[titleLines.length - 1]
    : '';

  // -------------------------
  // SKILLS
  // -------------------------

  const skillsMatch = detailsPart.match(
    /Skills:\s*([\s\S]*?)(?=\s*Description:)/i
  );

  const skills = skillsMatch
    ? skillsMatch[1].trim()
    : '';

  // -------------------------
  // DESCRIPTION
  // -------------------------

  const descriptionMatch = detailsPart.match(
    /Description:\s*([\s\S]*?)(?=\s*(?:https?:\/\/|\/projects\/|See more|$))/i
  );

  const description = descriptionMatch
    ? descriptionMatch[1].trim()
    : '';

  // -------------------------
  // PROJECT URL
  // -------------------------

  let url = '';

  const fullUrlMatch = detailsPart.match(
    /https?:\/\/(?:www\.)?freelancer\.com\/projects\/[^\s<>"\\]+/i
  );

  if (fullUrlMatch) {
    url = fullUrlMatch[0];
  } else {

    const relativeUrlMatch = detailsPart.match(
      /\/projects\/[^\s<>"\\]+/i
    );

    if (relativeUrlMatch) {
      url = 'https://www.freelancer.com' + relativeUrlMatch[0];
    }
  }

  // Remove tracking parameters
  url = url.split('?')[0];

  // Remove trailing characters
  url = url.replace(/[),>"']+$/, '');

  // -------------------------
  // ADD PROJECT
  // -------------------------

  if (title) {
    projects.push({
      title,
      budget,
      skills,
      description,
      url
    });
  }
}

return projects.map(project => ({
  json: project
}));

const items = $input.all();

const results = [];

for (const item of items) {
  const output = item.json.output?.[0]?.content?.[0]?.text;

  if (!output) {
    continue;
  }

  try {
    const result = JSON.parse(output);

    results.push({
      json: result
    });
  } catch (error) {
    results.push({
      json: {
        error: "Failed to parse AI response",
        raw_output: output
      }
    });
  }
}

return results;

