// All projects that came from the proposal parser
const projects = $('Code in JavaScript2').all().map(item => item.json);

// URLs that were found in Google Sheets
const existingUrls = $input.all()
  .map(item => item.json.URL)
  .filter(url => url);

const existingSet = new Set(existingUrls);

// Keep only projects that are NOT already in the sheet
const newProjects = projects.filter(project => {
  return project.url && !existingSet.has(project.url);
});

return newProjects.map(project => ({
  json: project
}));
